<?php get_header(); ?><main class="m2-page"><div class="m2-container"><div class="m2-section__head"><h1><?php bloginfo('name'); ?></h1><p><?php bloginfo('description'); ?></p></div><?php if(have_posts()): ?><div class="m2-blog-grid"><?php while(have_posts()): the_post(); ?><article class="m2-post"><div class="m2-post__body"><small><?php echo esc_html(get_the_date()); ?></small><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><?php the_excerpt(); ?><a class="m2-btn m2-btn--outline" href="<?php the_permalink(); ?>">Read more</a></div></article><?php endwhile; ?></div><?php the_posts_pagination(); ?><?php else: ?><p>No content found.</p><?php endif; ?></div></main><?php get_footer(); ?>